diff --git a/core/vm/predictor.go b/core/vm/predictor.go
index cab9aba..ca5429b 100644
--- a/core/vm/predictor.go
+++ b/core/vm/predictor.go
@@ -1,10 +1,39 @@
 package vm

+// WARMUP_OBSERVATIONS is read by the branch statistics in var_table.go.
 const WARMUP_OBSERVATIONS = 1

+const (
+	// stableBlocks is the number of distinct blocks in which a branch's current
+	// direction must have been observed, without any change in between, before
+	// the predictor overrides the ordering-based fallback. Observations made
+	// within one block see nearly the same state, so they count only once.
+	stableBlocks = 2
+	// retainBlocks is the number of distinct blocks with observations after
+	// which a branch is exempt from sweeping, so recurring branches keep their
+	// history while one-off branches are still swept.
+	retainBlocks = 2
+	// retained keeps observationCount above the sweeper's frequency threshold.
+	retained = 1 << 40
+)
+
+// Every replayed block issues all of its queries before any of its
+// observations, so the first ordinary query after an observation starts a
+// new block.
+var (
+	replayBlock int32
+	observing   bool
+)
+
 type predictor struct {
 	observationCount int
 	lastPred         []int
+
+	observed  int32 // observations received
+	seen      int32 // distinct blocks with observations
+	lastBlock int32 // block of the most recent observation
+	runBlocks int32 // distinct blocks spanned by the current run of lastDir
+	lastDir   int8  // most recent observed direction
 }

 func initPredictor() *predictor {
@@ -13,12 +42,43 @@ func initPredictor() *predictor {
 	}
 }

-func (p *predictor) predict(train bool) int { return uncertain }
+func (p *predictor) predict(train bool) int {
+	if !train && observing {
+		observing = false
+		replayBlock++
+	}
+	if p.observed == 0 {
+		return uncertain
+	}
+	if train || p.runBlocks >= stableBlocks {
+		return int(p.lastDir)
+	}
+	return uncertain
+}

 func (p *predictor) update(dir, predDir int) {
-	p.observationCount++
-	if p.observationCount > WARMUP_OBSERVATIONS {
-		p.observationCount = WARMUP_OBSERVATIONS
+	observing = true
+	if dir == taken || dir == notTaken {
+		if (p.observed == 0 || p.lastBlock != replayBlock) && p.seen < 1<<30 {
+			p.seen++
+		}
+		if p.observed < 1<<30 {
+			p.observed++
+		}
+		if int(p.lastDir) == dir {
+			if p.lastBlock != replayBlock && p.runBlocks < 1<<30 {
+				p.runBlocks++
+			}
+		} else {
+			p.lastDir = int8(dir)
+			p.runBlocks = 1
+		}
+		p.lastBlock = replayBlock
+	}
+	if p.seen >= retainBlocks {
+		p.observationCount = retained
+	} else {
+		p.observationCount++
 	}
 	if len(p.lastPred) > 1 {
 		p.lastPred = p.lastPred[1:]
